package com.example.crypto

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import kotlinx.serialization.*
import kotlinx.serialization.json.*

@Serializable
data class EncryptRequest(
    val plaintext: String,
    val context: String = "default"
)

@Serializable
data class DecryptRequest(
    val ciphertext: String,
    val nonce: String,
    val context: String = "default"
)

@Serializable
data class EncryptResponse(
    val ciphertext: String,
    val nonce: String,
    val keyId: String
)

object CryptoService {
    // Static AES-256-GCM key - loaded from env in production
    private val KEY_MATERIAL = System.getenv("ENCRYPTION_KEY") 
        ?: "0123456789abcdef0123456789abcdef" // 32 bytes for AES-256

    private val secretKey = SecretKeySpec(KEY_MATERIAL.toByteArray(), "AES")
    private val KEY_ID = "key-2024-prod-01"

    // VULNERABILITY: Nonce/IV is derived from user-supplied 'context' field
    // When the same context is reused, the same nonce is generated,
    // leading to nonce reuse in AES-GCM which breaks confidentiality
    private fun deriveNonce(context: String): ByteArray {
        val hash = java.security.MessageDigest.getInstance("SHA-256")
            .digest(context.toByteArray())
        return hash.copyOfRange(0, 12) // 96-bit nonce for GCM
    }

    fun encrypt(plaintext: String, context: String): EncryptResponse {
        val nonce = deriveNonce(context)
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(128, nonce)
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, spec)

        val ciphertextBytes = cipher.doFinal(plaintext.toByteArray(Charsets.UTF_8))

        return EncryptResponse(
            ciphertext = Base64.getEncoder().encodeToString(ciphertextBytes),
            nonce = Base64.getEncoder().encodeToString(nonce),
            keyId = KEY_ID
        )
    }

    fun decrypt(ciphertext: String, nonce: String, context: String): String {
        val nonceBytes = Base64.getDecoder().decode(nonce)
        val ciphertextBytes = Base64.getDecoder().decode(ciphertext)

        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val spec = GCMParameterSpec(128, nonceBytes)
        cipher.init(Cipher.DECRYPT_MODE, secretKey, spec)

        return String(cipher.doFinal(ciphertextBytes), Charsets.UTF_8)
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/v1/encrypt") {
                val body = call.receiveText()
                val request = Json.decodeFromString<EncryptRequest>(body)

                if (request.plaintext.length > 4096) {
                    call.respond(HttpStatusCode.BadRequest, "Plaintext too large")
                    return@post
                }

                val response = CryptoService.encrypt(request.plaintext, request.context)
                call.respond(HttpStatusCode.OK, Json.encodeToString(response))
            }

            post("/api/v1/decrypt") {
                val body = call.receiveText()
                val request = Json.decodeFromString<DecryptRequest>(body)
                val result = CryptoService.decrypt(
                    request.ciphertext, request.nonce, request.context
                )
                call.respond(HttpStatusCode.OK, result)
            }

            get("/health") {
                call.respond(HttpStatusCode.OK, "OK")
            }
        }
    }.start(wait = true)
}
